public class E202 {
    int a;
    int b;
    E202() { this(0, 0); }
    E202(int a, int b) { this.a = a; this.b = b; }
    int sum() { return a + b; }
    public static void main(String[] args) {
        E202 p = new E202();
        E202 q = new E202(2, 5);
        System.out.println(p.sum() + " " + q.sum());
    }
}
